  "notes": [
    "飾品與符文素材同屬飾品系統；物品名保留日文版名稱，效果以繁體中文重寫。",
    "無色飾品的百分比能力提升有不可疊加的例外；同色符文連結則可強化相應符文飾品。",
    "章節標記：3A 科利安德爾至蒼枯森林；3B 維爾諾亞至圖爾根礦山；3C 卡爾斯塔德至蘇爾斯火山；3D 克雷爾蒙費蘭至奉龍殿；5A 精靈森林至彩虹橋；5B 阿斯嘉特至瓦爾哈拉宮殿。",
    "商店表包含一般庫存與熟客製作；素材必須先出售，並非在合成選單直接製作。",
    "裝備及魔法數值來自玩家實測資料的交叉核對；少數來源符號不明或互相衝突之處直接標記。",
    "一般魔法依角色升級習得；大魔法依人物類型及法杖決定。大魔法不消耗表列的一般魔法 AP。"
  ],
